#!/bin/bash\n\n# Ravelaso.UiPath.Selenium — Quick Verification Script\n# Runs build, tests, and validation checks\n\nset -e\n\necho \"====================================================================\"\necho \"  Ravelaso.UiPath.Selenium — Verification Suite\"\necho \"====================================================================\"\necho \"\"\n\n# Step 1: Clean\necho \"🧹 Cleaning previous builds...\"\ndotnet clean -c Release --quiet 2>/dev/null || true\n\n# Step 2: Build\necho \"🔨 Building (net8.0 + net10.0)...\"\nif dotnet build -c Release; then\n    echo \"   ✅ Build succeeded (0 errors)\"\nelse\n    echo \"   ❌ Build failed\"\n    exit 1\nfi\n\necho \"\"\n\n# Step 3: Run Tests\necho \"🧪 Running Tests (30 unit + integration)...\"\nif cd Ravelaso.UiPath.Selenium.Tests && dotnet run -c Release --framework net10.0 2>&1 | grep -q \"ALL TESTS PASSED: 30/30\"; then\n    echo \"   ✅ All tests passed (30/30)\"\nelse\n    echo \"   ❌ Some tests failed\"\n    exit 1\nfi\n\ncd - > /dev/null\n\necho \"\"\necho \"====================================================================\"\necho \"  ✅ VERIFICATION COMPLETE\"\necho \"====================================================================\"\necho \"\"\necho \"📦 Artifacts ready in:\"\necho \"   - Core (net8.0):  ./Ravelaso.UiPath.Selenium.Core/bin/Release/net8.0/\"\necho \"   - Core (net10.0): ./Ravelaso.UiPath.Selenium.Core/bin/Release/net10.0/\"\necho \"\"\necho \"📚 Documentation:\"\necho \"   - API Reference: docs/api.md\"\necho \"   - Quick Start:   docs/QUICKSTART.md\"\necho \"   - Delivery:      DELIVERY.md\"\necho \"\"\necho \"🚀 Next: Integrate Core DLL into UiPath Studio 25.10\"\necho \"\"\n"